35	/** n-th (1-based) Sunday of a month (UTC day number), or last when n = -1. */
36	function sundayOf(year: number, month: number, n: number): number {
37	  if (n > 0) {
38	    const first = new Date(Date.UTC(year, month - 1, 1)).getUTCDay();
39	    return 1 + ((7 - first) % 7) + (n - 1) * 7;
