46	/** Manual America/Chicago offset (hours) for a UTC instant; used only if Intl is unavailable. */
47	function chicagoOffsetHours(ms: number): number {
48	  const y = new Date(ms).getUTCFullYear();
49	  let start: number, end: number;
50	  if (y >= 2007) {
51	    start = Date.UTC(y, 2, sundayOf(y, 3, 2), 8); // 2:00 CST = 08:00 UTC
