315	const SALT_WORDS = new Set([
316	  "potassium", "sodium", "calcium", "magnesium", "hydrochloride", "hcl", "dihydrochloride", "hydrobromide",
317	  "succinate", "tartrate", "besylate", "maleate", "mesylate", "fumarate", "citrate", "acetate", "sulfate",
