320	]);
321	// salts that are the drug itself when they stand alone
322	const SALT_KEEP_ALONE = /^(potassium chloride|sodium bicarbonate|calcium carbonate|magnesium oxide|sodium chloride|calcium acetate|sodium zirconium cyclosilicate)$/;
