324	function ingredientFrom(name: string): string | undefined {
325	  const lower = name.toLowerCase().trim();
326	  if (!lower) return undefined;
327	  // SBD style: "... [Brand]"
328	  const bracket = /\[([^\]]+)\]\s*$/.exec(lower);
329	  const body = lower.replace(/\[[^\]]*\]/g, " ").trim();
330	  // Combination products: "a 5 MG / b 500 MG Oral Tablet"
331	  const parts = body.split(/\s+\/\s+|\s*\/\s*(?=[a-z])/);
332	  const ings: string[] = [];
333	  for (const part of parts) {
334	    const words = part.split(/[\s,]+/).filter(Boolean);
335	    const lead: string[] = [];
336	    for (const w of words) {
337	      if (/^[\d.]/.test(w)) break;
338	      if (/^(oral|tablet|tablets|tab|capsule|capsules|cap|injectable|injection|solution|suspension|pen|prefilled|extended|delayed|release|topical|cream|ointment|patch|inhaler|spray|nasal|ophthalmic|chewable|sublingual|mg|mcg|ml|units?|unt|daily|po)$/.test(w))
339	        break;
340	      lead.push(w.replace(/[()]/g, ""));
341	    }
342	    let phrase = lead.join(" ").trim();
343	    if (!phrase) continue;
344	    const firstWord = phrase.split(" ")[0];
345	    if (BRANDS[firstWord] && !phrase.startsWith("insulin")) {
346	      ings.push(BRANDS[firstWord]);
347	      continue;
348	    }
349	    if (BRANDS[phrase]) {
350	      ings.push(BRANDS[phrase]);
351	      continue;
352	    }
353	    if (!SALT_KEEP_ALONE.test(phrase)) {
354	      const ws = phrase.split(" ");
355	      const kept = ws.filter((w, i) => i === 0 || !SALT_WORDS.has(w));
356	      phrase = kept.join(" ");
357	    }
358	    if (phrase) ings.push(phrase);
359	  }
360	  if (ings.length === 0 && bracket) {
361	    const b = bracket[1].trim().split(/\s+/)[0];
362	    if (BRANDS[b]) return BRANDS[b];
363	  }
364	  if (ings.length === 0) return undefined;
365	  return ings.join(" / ");
366	}
