368	function doseOf(d: unknown): MedicationRow["dose"] | undefined {
369	  if (!isObj(d)) return undefined;
370	  const v = num(d.value);
371	  const u = str(d.unit)?.trim().toLowerCase();
372	  if (v === undefined || !u) return undefined;
373	  const map: Record<string, "mg" | "mcg" | "units" | "mL" | "tablet"> = {
374	    mg: "mg",
375	    mcg: "mcg",
376	    ug: "mcg",
377	    "µg": "mcg",
378	    units: "units",
379	    unit: "units",
380	    unt: "units",
381	    u: "units",
382	    "[iu]": "units",
383	    iu: "units",
384	    ml: "mL",
385	    tab: "tablet",
386	    tabs: "tablet",
387	    tablet: "tablet",
388	    tablets: "tablet",
389	  };
390	  const unit = map[u];
391	  return unit ? { value: v, unit } : undefined;
392	}
