394	function freqOf(f: unknown, sig: string | undefined): MedicationRow["frequency"] | undefined {
395	  switch (f) {
396	    case "QD":
397	    case "BID":
398	    case "TID":
399	    case "QHS":
400	    case "PRN":
401	      return f;
402	    case "OTHER":
403	      if (sig && /\b(once (a |per |every )?week(ly)?|every week|weekly|q\s?week|qw)\b/i.test(sig)) return "QW";
404	      return "other";
405	    default:
406	      return undefined;
407	  }
