410	function isHospitalOnly(e: Record<string, any>): boolean {
411	  const text = `${str(e.drug?.name) ?? ""} ${str(e.sig) ?? ""}`;
412	  return /\b(intravenous|infusion|ivpb|iv piggyback|iv push|inpatient only)\b|\bIV\b/i.test(text);
