415	function mapMedications(byType: Map<string, Ev[]>): MedicationRow[] {
416	  const lines = groupBy(byType.get("med_event") ?? [], "med_id");
417	  const candidates: { key: string; last: Ev; row: MedicationRow }[] = [];
418	  for (const [medId, evs] of lines) {
419	    const valid = evs.filter((e) => ["start", "change", "hold", "resume", "stop"].includes(e.entry.action));
420	    if (valid.length === 0) continue;
421	    const last = valid[valid.length - 1];
422	    const e = last.entry;
423	    const name = str(e.drug?.name);
424	    if (!name) continue;
425	    if (isHospitalOnly(e)) continue;
426	    let status: MedicationRow["status"];
427	    let since: string | undefined;
428	    if (e.action === "hold") {
429	      status = "held";
430	      since = localDate(last.item.effective) ?? undefined;
431	    } else if (e.action === "stop") {
432	      status = "stopped";
433	      since = localDate(last.item.effective) ?? undefined;
434	    } else {
435	      status = "active";
436	      for (let i = valid.length - 1; i >= 0; i--) {
437	        const a = valid[i].entry.action;
438	        if (a === "start" || a === "resume") {
439	          since = localDate(valid[i].item.effective) ?? undefined;
440	          break;
441	        }
442	      }
443	    }
444	    const row: MedicationRow = { drug_name: name, status, patient_reported: false, evidence: evidenceOf(valid) };
445	    const ing = ingredientFrom(name);
446	    if (ing) row.ingredient = ing;
447	    if (since) row.status_since = since;
448	    const dose = doseOf(e.dose);
449	    if (dose) row.dose = dose;
450	    const freq = freqOf(e.frequency, str(e.sig));
451	    if (freq) row.frequency = freq;
452	    if (status === "stopped") {
453	      const sr = e.stop_reason;
454	      if (["adverse_reaction", "ineffective", "therapy_changed", "course_complete", "patient_choice", "other"].includes(sr))
455	        row.stop_reason = sr;
456	    }
457	    if (status === "held" || status === "stopped") {
458	      const rt = str(e.reason_text);
459	      if (rt) row.status_reason_text = rt;
460	    }
461	    candidates.push({ key: ing ? `ing:${ing}` : `line:${medId}`, last, row });
462	  }
463	  const best = new Map<string, { last: Ev; row: MedicationRow }>();
464	  for (const c of candidates) {
465	    const prev = best.get(c.key);
466	    if (!prev || cmpEv(prev.last, c.last) < 0) best.set(c.key, c);
467	  }
468	  return [...best.values()].sort((a, b) => cmpEv(a.last, b.last)).map((x) => x.row);
469	}
