473	function ckdStage(desc: string, icd: string | undefined): ProblemRow["ckd_stage"] | undefined {
474	  const d = desc.toLowerCase();
475	  const m = /\b(?:stage|g)\s*(1|2|3a|3b|4|5)\b/.exec(d) ?? /\bckd\s*(1|2|3a|3b|4|5)\b/.exec(d);
476	  if (m) {
477	    const s = m[1];
478	    return s === "3a" ? "G3a" : s === "3b" ? "G3b" : (`G${s}` as ProblemRow["ckd_stage"]);
479	  }
480	  if (/end[- ]stage renal|esrd|eskd|end[- ]stage kidney/.test(d)) return "G5";
481	  const c = (icd ?? "").toUpperCase();
482	  const codeMap: Record<string, ProblemRow["ckd_stage"]> = {
483	    "N18.1": "G1",
484	    "N18.2": "G2",
485	    "N18.31": "G3a",
486	    "N18.32": "G3b",
487	    "N18.4": "G4",
488	    "N18.5": "G5",
489	    "N18.6": "G5",
490	  };
491	  return codeMap[c];
492	}
493	
494	function albuminuria(desc: string): ProblemRow["albuminuria"] | undefined {
495	  const d = desc.toLowerCase();
496	  const m = /\ba\s*([123])\b/.exec(d);
497	  if (m && /albumin|g\s*(1|2|3a|3b|4|5)\s*\/?\s*a\s*[123]|\/\s*a\s*[123]|stage|ckd|kidney/.test(d)) return `A${m[1]}` as "A1" | "A2" | "A3";
498	  if (/severely increased albuminuria|macroalbuminuria/.test(d)) return "A3";
499	  if (/moderately increased albuminuria|microalbuminuria/.test(d)) return "A2";
500	  if (/normal to mildly increased albuminuria/.test(d)) return "A1";
501	  return undefined;
502	}
503	
504	function isCkd(desc: string, icd: string | undefined): boolean {
505	  return /^N18(\.|$)/i.test(icd ?? "") || /chronic kidney disease|\bckd\b/i.test(desc);
506	}
