508	/** ICD-10-CM adverse-effect-of-drug codes (T36–T50 with 6th character 5, and T88.7). */
509	function isAdverseEffectCode(icd: string | undefined): boolean {
510	  if (!icd) return false;
511	  return /^T(3[6-9]|4\d|50)\.[0-9A-Z]{2}5/i.test(icd) || /^T88\.7/i.test(icd);
512	}
