514	function mapProblems(byType: Map<string, Ev[]>): ProblemRow[] {
515	  const lines = groupBy(byType.get("problem_event") ?? [], "problem_id");
516	  const candidates: { key: string; last: Ev; row: ProblemRow }[] = [];
517	  for (const [pid, evs] of lines) {
518	    const valid = evs.filter((e) => ["add", "update", "resolve", "remove"].includes(e.entry.action));
519	    if (valid.length === 0) continue;
520	    let status: "active" | "resolved" | "removed" = "active";
521	    for (const e of valid) {
522	      if (e.entry.action === "add") status = "active";
523	      else if (e.entry.action === "resolve") status = "resolved";
524	      else if (e.entry.action === "remove") status = "removed";
525	    }
526	    if (status === "removed") continue;
527	    const last = valid[valid.length - 1];
528	    const e = last.entry;
529	    let desc: string | undefined;
530	    let icd: string | undefined;
531	    let snomed: string | undefined;
532	    let onset: ProblemRow["onset"];
533	    for (let i = valid.length - 1; i >= 0; i--) {
534	      const x = valid[i].entry;
535	      desc ??= str(x.description);
536	      icd ??= str(x.icd10cm);
537	      snomed ??= str(x.snomed);
538	      onset ??= fuzzy(x.onset);
539	    }
540	    desc = str(e.description) ?? desc;
541	    if (!desc) continue;
542	    if (isAdverseEffectCode(icd)) continue;
543	    const row: ProblemRow = { condition: desc, status, evidence: evidenceOf(valid) };
544	    if (icd) row.icd10cm = icd;
545	    if (snomed) row.snomed = snomed;
546	    if (onset) row.onset = onset;
547	    if (isCkd(desc, icd)) {
548	      const st = ckdStage(desc, icd);
549	      if (st) row.ckd_stage = st;
550	      const al = albuminuria(desc);
551	      if (al) row.albuminuria = al;
552	    }
553	    candidates.push({ key: icd ? `icd:${icd.toUpperCase()}` : `desc:${desc.toLowerCase()}|${pid}`, last, row });
554	  }
555	  const best = new Map<string, { last: Ev; row: ProblemRow }>();
556	  for (const c of candidates) {
557	    const prev = best.get(c.key);
558	    if (!prev || cmpEv(prev.last, c.last) < 0) best.set(c.key, c);
559	  }
560	  return [...best.values()].sort((a, b) => cmpEv(a.last, b.last)).map((x) => x.row);
561	}
