565	function mapAllergies(byType: Map<string, Ev[]>): AllergyIntoleranceRow[] {
566	  const lines = groupBy(byType.get("allergy_event") ?? [], "allergy_id");
567	  const out: { last: Ev; row: AllergyIntoleranceRow }[] = [];
568	  for (const evs of lines.values()) {
569	    const valid = evs.filter((e) => ["add", "update", "inactivate"].includes(e.entry.action));
570	    if (valid.length === 0) continue;
571	    const last = valid[valid.length - 1];
572	    if (last.entry.action === "inactivate") continue;
573	    const e = last.entry;
574	    const name = str(e.substance?.name);
575	    if (!name) continue;
576	    const rx = str(e.substance?.rxnorm);
577	    const type: AllergyIntoleranceRow["type"] =
578	      e.reaction_type === "allergy" || e.reaction_type === "intolerance" || e.reaction_type === "adverse_reaction"
579	        ? e.reaction_type
580	        : "allergy";
581	    if (!["allergy", "intolerance", "adverse_reaction"].includes(e.reaction_type)) {
582	      // unexpected kind; skip rather than guess
583	      continue;
584	    }
585	    const criticality: AllergyIntoleranceRow["criticality"] =
586	      e.severity === "low" || e.severity === "high" ? e.severity : "unknown";
587	    const row: AllergyIntoleranceRow = {
588	      substance: rx ? name.trim().toLowerCase() : name.trim(),
589	      type,
590	      criticality,
591	      evidence: evidenceOf(valid),
592	    };
593	    if (rx) row.rxnorm_ingredient = rx;
594	    const reactions = Array.isArray(e.reactions) ? e.reactions.filter((r: unknown) => typeof r === "string" && r.trim()) : [];
595	    if (reactions.length) row.reaction = reactions.join("; ");
596	    let onset: AllergyIntoleranceRow["onset"];
597	    for (let i = valid.length - 1; i >= 0 && !onset; i--) onset = fuzzy(valid[i].entry.onset);
598	    if (onset) row.onset = onset;
599	    out.push({ last, row });
600	  }
601	  return out.sort((a, b) => cmpEv(a.last, b.last)).map((x) => x.row);
602	}
