701	function analyteOf(test: Record<string, any>, resultCode: string): Analyte | undefined {
702	  const name = (str(test.name) ?? "").toLowerCase();
703	  const code = (str(test.nfm_code) ?? "").toUpperCase();
704	  const all = `${name} ${code.toLowerCase()} ${resultCode.toLowerCase()}`;
705	  // Never treat urine/point-of-care/meter components as serum analytes (UACR is handled first).
706	  if (/egfr|glomerular/.test(all) || /^EGFR/.test(code)) return "egfr";
707	  if (/albumin\s*\/\s*creat|albumin-to-creatinine|albumin creatinine ratio|\buacr\b|microalb.*creat/.test(all)) return "uacr";
708	  const urine = /\burine\b|\bur\b|\burn\b|\bu-/.test(name);
709	  const poc = /\bpoc\b|point[- ]of[- ]care|meter|fingerstick|capillary/.test(name);
710	  const loinc = str(test.loinc);
711	  let a: Analyte | undefined;
712	  if (loinc && LOINC_MAP[loinc]) a = LOINC_MAP[loinc];
713	  if (!a) a = CODE_MAP[code.replace(/[^A-Z0-9]/g, "")];
714	  if (!a) {
715	    if (/creatinine/.test(name)) a = "creatinine";
716	    else if (/potassium/.test(name)) a = "potassium";
717	    else if (/sodium/.test(name)) a = "sodium";
718	    else if (/chloride/.test(name)) a = "chloride";
719	    else if (/anion gap/.test(name)) a = "anion_gap";
720	    else if (/bicarbonate|\bco2\b|carbon dioxide/.test(name) && !/pco2|partial/.test(name)) a = "bicarbonate";
721	    else if (/urea nitrogen|\bbun\b/.test(name)) a = "bun";
722	    else if (/a1c|glycated h|glycohemoglobin/.test(name)) a = "a1c";
723	    else if (/glucose/.test(name)) a = "glucose";
724	    else if (/platelet/.test(name)) a = "platelets";
725	    else if (/white blood|\bwbc\b|leukocyte/.test(name)) a = "wbc";
726	    else if (/hemoglobin|\bhgb\b/.test(name)) a = "hemoglobin";
727	    else if (/hydroxybutyr|\bbhb\b/.test(name)) a = "bhb";
728	    else if (/\bpco2\b|partial pressure.*co2|carbon dioxide.*partial/.test(name)) a = "pco2";
729	    else if (/\bph\b/.test(name)) a = "ph";
730	    else if (/lipase/.test(name)) a = "lipase";
731	    else if (/troponin/.test(name) && !/troponin t\b/.test(name)) a = "troponin";
732	    else if (/\bhdl\b/.test(name)) a = "hdl";
733	    else if (/\bldl\b/.test(name)) a = "ldl";
734	    else if (/triglyceride/.test(name)) a = "triglycerides";
735	    else if (/cholesterol/.test(name) && !/non[- ]hdl|vldl/.test(name)) a = "cholesterol";
736	  }
737	  if (!a) return undefined;
738	  if (urine && a !== "uacr") return undefined;
739	  if (poc && a === "glucose") return undefined;
740	  if (a === "troponin" && /troponin t\b/.test(name)) return undefined;
741	  if (a === "cholesterol" && /non[- ]hdl|vldl/.test(name)) return undefined;
742	  return a;
743	}
744	
745	const UNIT_OF: Record<Analyte, string> = {
746	  creatinine: "mg/dL",
747	  egfr: "mL/min/1.73m2",
748	  potassium: "mmol/L",
749	  sodium: "mmol/L",
750	  chloride: "mmol/L",
751	  bicarbonate: "mmol/L",
752	  anion_gap: "mmol/L",
753	  bun: "mg/dL",
754	  glucose: "mg/dL",
755	  a1c: "%",
756	  uacr: "mg/g",
757	  platelets: "10*3/uL",
758	  wbc: "10*3/uL",
759	  hemoglobin: "g/dL",
760	  bhb: "mmol/L",
761	  ph: "[pH]",
762	  pco2: "mmHg",
763	  lipase: "U/L",
764	  troponin: "ng/mL",
765	  cholesterol: "mg/dL",
766	  triglycerides: "mg/dL",
767	  hdl: "mg/dL",
768	  ldl: "mg/dL",
769	};
770	
771	function normUnit(u: string): string {
772	  return u.toLowerCase().replace(/\s+/g, "").replace(/µ|μ/g, "u");
773	}
774	
775	/** Factor that converts the filed unit into the consumer unit, or null when the unit is not recognised. */
776	function unitFactor(a: Analyte, unitRaw: string): number | null {
777	  const u = normUnit(unitRaw);
778	  switch (a) {
779	    case "creatinine":
780	    case "bun":
781	    case "cholesterol":
782	    case "triglycerides":
783	    case "hdl":
784	    case "ldl":
785	      if (u === "mg/dl") return 1;
786	      return null;
787	    case "glucose":
788	      if (u === "mg/dl") return 1;
789	      return null;
790	    case "egfr":
791	      if (/^ml\/min(\/1\.73m(2|\^2|²)|\/1\.73sq\.?m|\/1\.73)?$/.test(u)) return 1;
792	      return null;
793	    case "potassium":
794	    case "sodium":
795	    case "chloride":
796	    case "bicarbonate":
797	    case "anion_gap":
798	    case "bhb":
799	      if (u === "mmol/l" || u === "meq/l") return 1;
800	      return null;
801	    case "a1c":
802	      if (u === "%" || u === "%ofhgb" || u === "%hba1c" || u === "%(ngsp)") return 1;
803	      return null;
804	    case "uacr":
805	      if (u === "mg/g" || u === "mg/gcreat" || u === "mg/gcr" || u === "ug/mgcreat" || u === "ug/mg" || u === "mcg/mgcreat" || u === "mcg/mg") return 1;
806	      return null;
807	    case "platelets":
808	    case "wbc":
809	      if (u === "cells/ul" || u === "/ul" || u === "cells/mm3" || u === "/mm3") return 1 / 1000;
810	      if (u === "k/ul" || u === "10*3/ul" || u === "x10e3/ul" || u === "10^3/ul" || u === "thou/ul" || u === "x10^3/ul" || u === "10*9/l" || u === "x10e9/l" || u === "10^9/l")
811	        return 1;
812	      return null;
813	    case "hemoglobin":
814	      if (u === "g/dl") return 1;
815	      if (u === "g/l") return 0.1;
816	      return null;
817	    case "ph":
818	      if (u === "" || u === "[ph]" || u === "ph" || u === "units") return 1;
819	      return null;
820	    case "pco2":
821	      if (u === "mmhg" || u === "mm[hg]") return 1;
822	      return null;
823	    case "lipase":
824	      if (u === "u/l" || u === "iu/l") return 1;
825	      return null;
826	    case "troponin":
827	      if (u === "ng/ml") return 1;
828	      if (u === "ng/l" || u === "pg/ml") return 0.001;
829	      return null;
830	  }
831	  return null;
832	}
833	
834	function parseValue(v: unknown): { value: number; comparator?: LabResultRow["comparator"] } | null {
835	  if (typeof v === "number" && isFinite(v)) return { value: v };
836	  if (typeof v !== "string") return null;
837	  const m = /^\s*(<=|>=|<|>|≤|≥)?\s*([-+]?(?:\d+(?:\.\d*)?|\.\d+))\s*$/.exec(v);
838	  if (!m) return null;
839	  const value = parseFloat(m[2]);
840	  if (!isFinite(value)) return null;
841	  const c = m[1] === "≤" ? "<=" : m[1] === "≥" ? ">=" : (m[1] as LabResultRow["comparator"] | undefined);
842	  return c ? { value, comparator: c } : { value };
843	}
844	
845	function egfrEquation(test: Record<string, any>, comment: string, resultCode: string): LabResultRow["egfr_equation"] {
846	  const find = (s: string): LabResultRow["egfr_equation"] | undefined => {
847	    const t = s.toLowerCase();
848	    const hits: [number, LabResultRow["egfr_equation"]][] = [];
849	    const add = (re: RegExp, eq: LabResultRow["egfr_equation"]) => {
850	      const m = re.exec(t);
851	      if (m) hits.push([m.index, eq]);
852	    };
853	    add(/ckd[- ]?epi[^.;]*?2021|2021[^.;]*?ckd[- ]?epi|race[- ]free/, "ckd-epi-2021");
854	    add(/ckd[- ]?epi[^.;]*?2009|2009[^.;]*?ckd[- ]?epi/, "ckd-epi-2009");
855	    add(/\bmdrd\b/, "mdrd");
856	    if (!hits.length) return undefined;
857	    hits.sort((a, b) => a[0] - b[0]);
858	    return hits[0][1];
859	  };
860	  return (
861	    find(comment) ??
862	    find(str(test.name) ?? "") ??
863	    (() => {
864	      const rc = resultCode.toUpperCase();
865	      if (/EGFR21|EGFR-?2021|CKDEPI21/.test(rc)) return "ckd-epi-2021" as const;
866	      if (/EGFR09|EGFR-?2009|CKDEPI09/.test(rc)) return "ckd-epi-2009" as const;
867	      if (/MDRD/.test(rc)) return "mdrd" as const;
868	      return undefined;
869	    })() ??
870	    "unknown"
871	  );
872	}
873	
874	/** 'race' when the component is the race-coefficient variant, 'nonrace' when it is the explicit non-race variant. */
875	function egfrRaceVariant(test: Record<string, any>, comment: string, resultCode: string): "race" | "nonrace" | "none" {
876	  const text = `${str(test.name) ?? ""} ${comment}`.toLowerCase();
877	  const code = (str(test.nfm_code) ?? "").toUpperCase();
878	  const rc = resultCode.toUpperCase();
879	  if (/non[- ]?(african|black)|not african|\bnon[- ]?aa\b/.test(text) || /(^|-)NAA$/.test(code) || /EGFR\d*N$/.test(rc))
880	    return "nonrace";
881	  if (/african[- ]american|\bblack\b|\baa\b/.test(text) || /(^|-)AA$/.test(code) || /EGFR\d*A$/.test(rc)) return "race";
882	  return "none";
883	}
884	
885	const STATUS_RANK: Record<string, number> = { P: 1, F: 2, C: 3 };
886	
887	function mapLabs(byType: Map<string, Ev[]>): LabResultRow[] {
888	  const evs = byType.get("imported_result") ?? [];
889	  // One copy per accession + component: the most advanced status, then the latest filed.
890	  const groups = new Map<string, Ev>();
891	  for (const ev of evs) {
892	    const e = ev.entry;
893	    if (!isObj(e.test)) continue;
894	    const acc = str(e.external_ref?.accession) ?? `item:${ev.item.id}`;
895	    const comp = `${str(e.test.nfm_code) ?? ""}|${str(e.external_ref?.result_code) ?? ""}|${str(e.test.name) ?? ""}`;
896	    const key = `${acc}|${comp}`;
897	    const prev = groups.get(key);
898	    if (!prev) {
899	      groups.set(key, ev);
900	      continue;
901	    }
902	    const rp = STATUS_RANK[prev.entry.result_status] ?? 0;
903	    const rn = STATUS_RANK[e.result_status] ?? 0;
904	    if (rn > rp || (rn === rp && (ev.r > prev.r || (ev.r === prev.r && ev.item.id > prev.item.id)))) groups.set(key, ev);
905	  }
906	
907	  type Cand = { ev: Ev; row: LabResultRow; acc: string; race: "race" | "nonrace" | "none" };
908	  const cands: Cand[] = [];
909	  for (const ev of groups.values()) {
910	    const e = ev.entry;
911	    const status = e.result_status;
912	    if (status !== "P" && status !== "F" && status !== "C") continue;
913	    const resultCode = str(e.external_ref?.result_code) ?? "";
914	    const analyte = analyteOf(e.test, resultCode);
915	    if (!analyte) continue;
916	    const pv = parseValue(e.value);
917	    if (!pv) continue;
918	    const factor = unitFactor(analyte, typeof e.unit === "string" ? e.unit : "");
919	    if (factor === null) continue;
920	    const collected = str(e.collected) ?? str(ev.item.effective);
921	    if (!collected) continue;
922	    const comment = str(e.comment) ?? "";
923	    const row: LabResultRow = {
924	      analyte,
925	      value: clean(pv.value * factor),
926	      unit: UNIT_OF[analyte],
927	      collected,
928	      status: status === "P" ? "preliminary" : "final",
929	      evidence: [{ item_id: ev.item.id, entry_id: ev.entryId }],
930	    };
931	    if (pv.comparator) row.comparator = pv.comparator;
932	    if (analyte === "egfr") row.egfr_equation = egfrEquation(e.test, comment, resultCode);
933	    const loinc = str(e.test.loinc);
934	    if (loinc) row.loinc = loinc;
935	    const acc = str(e.external_ref?.accession) ?? `item:${ev.item.id}`;
936	    cands.push({
937	      ev,
938	      row,
939	      acc,
940	      race: analyte === "egfr" ? egfrRaceVariant(e.test, comment, resultCode) : "none",
941	    });
942	  }
943	  // eGFR: drop the race-coefficient variant when the same specimen has a race-free variant of that calculation.
944	  const out = cands.filter((c) => {
945	    if (c.row.analyte !== "egfr" || c.race !== "race") return true;
946	    return !cands.some(
947	      (o) =>
948	        o !== c &&
949	        o.row.analyte === "egfr" &&
950	        o.acc === c.acc &&
951	        o.race !== "race" &&
952	        (o.row.egfr_equation === c.row.egfr_equation || o.row.egfr_equation === "unknown" || c.row.egfr_equation === "unknown"),
953	    );
954	  });
955	  out.sort((a, b) => {
956	    const ta = sortKey(a.row.collected);
957	    const tb = sortKey(b.row.collected);
958	    if (ta !== tb) return (isNaN(ta) ? 0 : ta) - (isNaN(tb) ? 0 : tb);
959	    return cmpEv(a.ev, b.ev);
960	  });
961	  return out.map((c) => c.row);
962	}
963	
964	// ───────────────────────────────────────────── vitals ─────────────────────────────────────────────
965	
966	function parseBp(s: unknown): [number, number] | null {
967	  if (typeof s !== "string") return null;
968	  const m = /^\s*(\d{2,3})\s*\/\s*(\d{2,3})\s*$/.exec(s);
969	  if (!m) return null;
970	  return [parseInt(m[1], 10), parseInt(m[2], 10)];
971	}
972	
973	function mapVitals(byType: Map<string, Ev[]>): VitalRow[] {
974	  const evs = [...(byType.get("vital_set") ?? [])].sort(cmpEv);
975	  const out: VitalRow[] = [];
976	  for (const ev of evs) {
977	    const e = ev.entry;
978	    const eff = typeof ev.item.effective === "string" ? ev.item.effective : "";
979	    const t = HAS_TIME.test(eff) ? Date.parse(eff) : Date.parse(String(ev.item.recorded));
980	    const local = localDateTime(t);
981	    if (!local) continue;
982	    const row: VitalRow = { setting: "clinic", local_time: local, evidence: [{ item_id: ev.item.id, entry_id: ev.entryId }] };
983	    let any = false;
984	    const bp = parseBp(e.bp);
985	    if (bp) {
986	      row.systolic_mmhg = bp[0];
987	      row.diastolic_mmhg = bp[1];
988	      any = true;
989	    }
990	    const rep = parseBp(e.bp_repeat);
991	    if (rep) {
992	      row.repeat_systolic_mmhg = rep[0];
993	      row.repeat_diastolic_mmhg = rep[1];
994	      any = true;
995	    }
996	    const pulse = num(e.pulse_bpm);
997	    if (pulse !== undefined) {
998	      row.pulse_bpm = pulse;
999	      any = true;
1000	    }
1001	    const wt = num(e.weight_lb);
1002	    if (wt !== undefined && wt > 0) {
1003	      row.weight_kg = Math.round(wt * 0.45359237 * 10) / 10;
1004	      any = true;
1005	    }
1006	    if (any) out.push(row);
1007	  }
1008	  return out;
1009	}
1010	
1011	// ───────────────────────────────────────────── entry point ─────────────────────────────────────────────
1012	
1013	export function transform(items: FolioItem[], asOf: string): ViewRows {
1014	  const empty: ViewRows = { medications: [], problems: [], allergies: [], labs: [], vitals: [] };
1015	  if (typeof asOf !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(asOf)) return empty;
1016	  let byType: Map<string, Ev[]>;
1017	  try {
1018	    byType = collect(currentItems(items, asOf));
1019	  } catch {
1020	    return empty;
1021	  }
1022	  const safe = <T>(f: () => T[]): T[] => {
1023	    try {
1024	      return f();
1025	    } catch {
1026	      return [];
1027	    }
1028	  };
1029	  return {
1030	    medications: safe(() => mapMedications(byType)),
1031	    problems: safe(() => mapProblems(byType)),
1032	    allergies: safe(() => mapAllergies(byType)),
1033	    labs: safe(() => mapLabs(byType)),
1034	    vitals: safe(() => mapVitals(byType)),
1035	  };
1036	}
